import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Build CUDA extension with a single fused kernel for GELU
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void gelu_fused_kernel(const float* __restrict__ x, float* __restrict__ y, long long N) {
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)blockDim.x * gridDim.x;

    const float k = 0.7978845608028654f; // sqrt(2.0 / pi)
    for (long long i = idx; i < N; i += stride) {
        float v = x[i];
        float v3 = v * v * v;
        float inner = k * (v + 0.044715f * v3);
        float t = tanhf(inner);
        y[i] = 0.5f * v * (1.0f + t);
    }
}

torch::Tensor gelu_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Input must be float32");

    auto x_contig = x.contiguous();
    auto y = at::empty_like(x_contig);
    long long N = x_contig.numel();

    int threads = 256;
    // Use enough blocks; cap to CUDA grid limits
    long long blocks_ll = (N + threads - 1) / threads;
    int blocks = (int)min(blocks_ll, (long long)65535);

    auto stream = at::cuda::getCurrentCUDAStream();
    gelu_fused_kernel<<<blocks, threads, 0, stream>>>(
        x_contig.data_ptr<float>(),
        y.data_ptr<float>(),
        N
    );
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "gelu_fused_kernel launch failed: ", cudaGetErrorString(err));

    return y.view(x.sizes());
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu_forward", &gelu_forward, "Fused GELU forward (CUDA)");
}
"""

_ext = load_inline(
    name="fused_gelu_ext",
    cpp_sources=[],
    cuda_sources=[_cuda_src],
    with_cuda=True,
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        orig_device = x.device
        if orig_device.type != "cuda":
            x = x.to("cuda")
        if x.dtype != torch.float32:
            x = x.float()
        y = _ext.gelu_forward(x)
        if orig_device.type != "cuda":
            y = y.to(orig_device)
        return y

